"""Disposable hot journals generated by SQLite; no real cases or providers."""
from contextlib import closing
import json
import os
from pathlib import Path
import sqlite3
import subprocess
import sys
import time

import pytest

from forensic_assistant import activity
from forensic_assistant.artifacts import browser, sqlite_recovery as service, ingest
from forensic_assistant.artifacts.browser_journal import SnapshotError
from forensic_assistant.database.db import connect
from test_browser_parser import history
from test_browser_safety import batch, local_runner


def hot(path):
    with closing(history(path)) as db:
        db.execute('CREATE TABLE padding(id INTEGER PRIMARY KEY,b BLOB)')
        with db: db.executemany('INSERT INTO padding(b) VALUES (?)', [(bytes(4096),)]*10)
    code = '''import sqlite3,sys,os
d=sqlite3.connect(sys.argv[1]);d.execute('PRAGMA cache_size=1')
d.execute('BEGIN IMMEDIATE');d.execute('UPDATE padding SET b=randomblob(4096)')
os._exit(0)
'''
    subprocess.run([sys.executable, '-c', code, str(path)], check=True, timeout=10)
    return path


def captured(path):
    return {s: Path(str(path)+s).read_bytes() for s in ('','-journal','-wal','-shm') if Path(str(path)+s).exists()}


@pytest.fixture
def source(tmp_path):
    return hot(tmp_path/'History')


@pytest.fixture
def audited(tmp_path):
    case = tmp_path/'case.db'
    with closing(connect(case)) as db, activity.bind(activity.Session(case)):
        yield db, case


def test_actual_recovery_and_provenance(source, tmp_path, audited):
    _, case = audited
    original = captured(source)
    options = browser.snapshot(source, tmp_path/'copy', 'edge', 'Default')
    working = options.pop('_database_path')
    proof = options['recovery']
    assert proof['category'] == 'recovery_succeeded' and proof['disposable_copy']
    assert proof['derived']['sha256'] == service.digest(working)
    assert proof['original_manifest'] == browser.inventory(source)
    assert proof['derived']['sha256'] != proof['original_manifest']['']['sha256']
    assert captured(tmp_path/'copy') == original and captured(source) == original
    with closing(sqlite3.connect(Path(working).as_uri()+'?mode=ro', uri=True)) as db:
        assert db.execute('SELECT count(*) FROM padding WHERE b!=zeroblob(4096)').fetchone()[0] == 0
    rows = list(browser.parse(working, proof['original_manifest']['']['sha256'], **options))
    assert len(rows) == 2 and rows[0]['timestamps'][0]['precision_ns'] == 1000
    assert 'disposable derived copy' in rows[0]['record']['warnings_json']
    service.release(working, proof)
    events = [json.loads(line) for line in activity.sidecar(case).read_text().splitlines()]
    completed = [e for e in events if e['action'] == 'SQLITE_RECOVERY' and e['phase'] == 'complete']
    assert len(completed) == 1 and completed[0]['transformation']['derived'] == proof['derived']
    assert any(e['action'] == 'SQLITE_RECOVERY_CLEANUP' for e in events)
    assert activity.inspect(activity.sidecar(case))['valid']
    assert not Path(working).parent.exists()
    assert captured(source) == original


def test_retry_source_occurrences_and_failed_history(source, audited):
    db, case = audited
    bid = batch(db)
    def run():
        return ingest.ingest_artifact(db, source, 'browser', browser_product='edge', profile='Default',
                                      batch_id=bid, runner=local_runner)
    journal = Path(str(source)+'-journal'); good = journal.read_bytes()
    journal.write_bytes(b'malformed')
    assert run()['status'] == 'failed'
    journal.write_bytes(good)
    first, second = run(), run()
    assert first['inserted'] == 2 and first['status'] == 'complete'
    assert second['inserted'] == 0 and second['duplicates'] == 2
    assert [r[0] for r in db.execute('SELECT status FROM ingestion_runs ORDER BY id')] == ['failed','complete','complete']
    assert db.execute('SELECT count(*) FROM browser_record_occurrences').fetchone()[0] == 4
    assert db.execute('SELECT count(*) FROM sources').fetchone()[0] == 1
    params = json.loads(db.execute('SELECT parameters_json FROM artifact_runs ORDER BY run_id DESC LIMIT 1').fetchone()[0])
    assert params['recovery']['original_manifest']['']['sha256'] != params['recovery']['derived']['sha256']
    assert params['recovery']['source_context']['source_id'] == db.execute('SELECT source_id FROM ingestion_batches WHERE batch_id=?',(bid,)).fetchone()[0]
    assert db.execute('SELECT DISTINCT file_sha256 FROM evidence_records').fetchone()[0] == params['manifest']['']['sha256']


@pytest.mark.parametrize('damage,category', [('checksum','journal_malformed'),('truncated','journal_incomplete'),
    ('external','recovery_unsupported'), ('database','inconsistent_acquisition'), ('mixed','recovery_unsupported')])
def test_invalid_recovery_never_opens_writable_sqlite(source, monkeypatch, damage, category):
    journal = Path(str(source)+'-journal')
    raw = bytearray(journal.read_bytes())
    if damage == 'checksum': raw[512+4+4096-200] ^= 1; journal.write_bytes(raw)
    elif damage == 'truncated': journal.write_bytes(raw[:-1])
    elif damage == 'external': journal.write_bytes(raw + bytes(8) + service.MAGIC)
    elif damage == 'database': source.write_bytes(source.read_bytes()[:-1])
    else: Path(str(source)+'-wal').write_bytes(b'conflicting')
    original = captured(source)
    monkeypatch.setattr(sqlite3,'connect',lambda *a,**k: pytest.fail('SQLite entered before eligibility'))
    with pytest.raises(SnapshotError) as caught:
        service.eligible(source,browser.inventory(source),time.monotonic()+30)
    assert caught.value.diagnostics['category'] == category
    assert captured(source) == original


@pytest.mark.parametrize('phase', ['intent','start','complete','cleanup'])
def test_mandatory_audit_failure_blocks_publication(source, audited, monkeypatch, phase):
    db, _ = audited
    session = activity.CURRENT.get(); record = session.record
    def fail(action, *args, **kwargs):
        matches = ((phase in ('intent','complete') and action == 'SQLITE_RECOVERY' and kwargs.get('phase') == phase)
                   or phase == 'start' and action == 'SQLITE_RECOVERY_START'
                   or phase == 'cleanup' and action == 'SQLITE_RECOVERY_CLEANUP')
        if matches: raise activity.AuditError('synthetic mandatory audit failure')
        return record(action,*args,**kwargs)
    monkeypatch.setattr(session,'record',fail)
    result = ingest.ingest_artifact(db,source,'browser',browser_product='edge',profile='Default',batch_id=batch(db),runner=local_runner)
    assert result['status'] == 'failed' and result['inserted'] == 0
    assert db.execute('SELECT count(*) FROM evidence_records').fetchone()[0] == 0


def test_space_and_deadline_limits(source, tmp_path, monkeypatch):
    manifest = browser.inventory(source)
    with pytest.raises(SnapshotError) as caught: service.eligible(source,manifest,0)
    assert caught.value.diagnostics['category'] == 'resource_limit'
    monkeypatch.setattr(service,'MAX_BYTES',1)
    with pytest.raises(SnapshotError) as caught:
        service.recover_worker(source,tmp_path/'control',dict(manifest=manifest))
    assert caught.value.diagnostics['category'] == 'resource_limit'
    assert not (tmp_path/'sqlite-working').exists()


def test_redirected_working_directory_refused(source, tmp_path):
    outside = tmp_path/'outside';outside.mkdir()
    root = tmp_path/'sqlite-working'
    try: root.symlink_to(outside,target_is_directory=True)
    except OSError: pytest.skip('Symlink privilege unavailable')
    with pytest.raises((OSError,ValueError)):
        service.recover_worker(source,tmp_path/'control',dict(manifest=browser.inventory(source)))
    assert list(outside.iterdir()) == []


@pytest.mark.parametrize('stage', ['recovery','validation'])
def test_sqlite_failures_preserve_acquisition(source,tmp_path,monkeypatch,stage):
    original = captured(source)
    if stage == 'recovery':
        def fail(*a,**k): raise sqlite3.OperationalError('private SQL content')
        monkeypatch.setattr(sqlite3,'connect',fail)
    else:
        def fail(*a,**k): raise SnapshotError('sqlite_validation_failed','synthetic',{})
        monkeypatch.setattr(service,'validate',fail)
    with pytest.raises(SnapshotError) as caught:
        service.recover_worker(source,tmp_path/'control',dict(manifest=browser.inventory(source)))
    assert caught.value.diagnostics['category'] == ('sqlite_recovery_failed' if stage=='recovery' else 'derived_validation_failed')
    assert caught.value.diagnostics['recovery_attempted'] is True
    assert 'private SQL content' not in str(caught.value)
    assert captured(source) == original


def test_private_acquisition_is_pinned_during_dispatch(source,tmp_path,audited,monkeypatch):
    real = ingest.worker
    def checked(kind,path,*args):
        if kind == 'sqlite_recovery' and os.name == 'nt':
            with pytest.raises(OSError):
                with Path(path).open('r+b') as stream: stream.write(b'forbidden')
        return real(kind,path,*args)
    monkeypatch.setattr(ingest,'worker',checked)
    options=browser.snapshot(source,tmp_path/'copy','edge','Default')
    assert options['recovery']['category']=='recovery_succeeded'
    service.release(options['_database_path'],options['recovery'])


@pytest.mark.parametrize('cancel', [False,True])
def test_hung_recovery_contained_and_cleaned(source,audited,monkeypatch,cancel):
    from test_evtx_worker import assert_gone
    db,_ = audited
    original = ingest.subprocess.Popen; processes=[]; stages=[]
    code = '''import runpy,time
from forensic_assistant.artifacts import sqlite_recovery as s
def hang(*a): time.sleep(60)
s.recover_worker=hang
runpy.run_module('forensic_assistant.artifacts.worker',run_name='__main__')
'''
    def launch(args,**kwargs):
        if 'sqlite_recovery' in args:
            stages.append(Path(args[6]))
            proc=original([args[0],'-c',code,*args[3:]],**kwargs);processes.append(proc);return proc
        return original(args,**kwargs)
    monkeypatch.setattr(ingest.subprocess,'Popen',launch)
    monkeypatch.setattr(service,'TIMEOUT',1)
    real_sleep=ingest.time.sleep
    def sleep(seconds):
        if cancel and processes: raise KeyboardInterrupt
        real_sleep(seconds)
    monkeypatch.setattr(ingest.time,'sleep',sleep)
    def run(): return ingest.ingest_artifact(db,source,'browser',browser_product='edge',profile='Default',batch_id=batch(db))
    if cancel:
        with pytest.raises(KeyboardInterrupt):run()
    else: assert run()['status']=='failed'
    for process in processes: assert process.poll() is not None; assert_gone(process.pid)
    assert stages and all(not stage.parent.exists() for stage in stages)
    assert db.execute('SELECT count(*) FROM evidence_records').fetchone()[0]==0


def test_shared_reason_and_partial_semantic_style():
    from forensic_assistant.ingest.presentation import render
    from forensic_assistant.terminal import Palette, SGR
    p=Palette(True)
    row=dict(status='failed',inserted=0,duplicates=0,errors=1,source_type='browser',
             diagnostics=[dict(message='SQLite rollback rejected',details={'category':'journal_malformed'})])
    text=render(dict(results=[row]),p)
    assert text.index('Outcome:') < text.index('Reason:') < text.index('Records retained')
    assert p('error','SQLite rollback rejected') in text and p('error','1') in text
    row['status']='partial'
    text=render(dict(results=[row]),p)
    assert p('forensic_note','  SQLite rollback rejected') in text
    assert '\x1b' not in json.dumps(row)
    assert '\x1b' not in SGR.sub('',text)
